package candidate

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"net/http"
	"sort"
	"strings"
)

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		for _, id := range ids {
			if strings.ContainsRune(id, 0) {
				return protocol.Result{}, false, &protocol.Rejection{Status: 404}
			}
		}

		// Sort IDs by UTF-8 byte order for deterministic hash
		sortedIDs := append([]string(nil), ids...)
		sort.Strings(sortedIDs)

		// Compute requestHash: "bulk-approve.v3\n" + sorted "<length>:<id>" pairs
		hashInput := "bulk-approve.v3\n"
		for _, id := range sortedIDs {
			hashInput += fmt.Sprintf("%d:%s", len(id), id)
		}
		hash := sha256.Sum256([]byte(hashInput))
		requestHash := hex.EncodeToString(hash[:])

		// Prepare response JSON bytes
		responseBytes := fmt.Sprintf(`{"approvedIds":[%s]}`, func() string {
			parts := make([]string, len(sortedIDs))
			for i, id := range sortedIDs {
				parts[i] = `"` + id + `"`
			}
			return strings.Join(parts, ",")
		}())

		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer tx.Rollback(ctx)

		// Set session context
		_, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Check if idempotency key already exists in this scope
		var existingAction pgx.Row
		var actionExists bool
		var responseStored string
		var approvedIDsStored []string

		existingAction = tx.QueryRow(ctx, `SELECT response FROM "ActionRequest" 
			WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`, 
			u.Tenant, u.User, "bulk-approve.v3", key)

		err = existingAction.Scan(&responseStored)
		if err == pgx.ErrNoRows {
			actionExists = false
		} else if err != nil {
			return protocol.Result{}, false, err
		} else {
			actionExists = true
			// Parse stored response to extract approved IDs for comparison
			var storedResult protocol.Result
			if err := json.Unmarshal([]byte(responseStored), &storedResult); err == nil {
				approvedIDsStored = storedResult.ApprovedIDs
			}
		}

		// If action exists, check if it's a replay (same IDs) or conflict (different IDs)
		if actionExists {
			// Compare sorted IDs
			if len(approvedIDsStored) != len(sortedIDs) {
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}
			for i := range sortedIDs {
				if approvedIDsStored[i] != sortedIDs[i] {
					return protocol.Result{}, false, &protocol.Rejection{Status: 409}
				}
			}
			// Same IDs - replay, return stored response
			var storedApprovedIDs []string
			if err := json.Unmarshal([]byte(responseStored), &storedApprovedIDs); err == nil {
				return protocol.Result{ApprovedIDs: storedApprovedIDs}, true, nil
			}
			// Fallback if parsing fails
			return protocol.Result{ApprovedIDs: approvedIDsStored}, true, nil
		}

		// Check which IDs are eligible for approval
		rows, err := tx.Query(ctx, `SELECT id FROM "Purchase" 
			WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted' 
			ORDER BY id FOR UPDATE`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}

		eligible := []string{}
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.Result{}, false, err
		}

		// If any target is invalid (missing or not approved), reject all
		if len(eligible) != len(ids) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Update all Purchase records to approved
		tag, err := tx.Exec(ctx, `UPDATE "Purchase" SET status='approved' 
			WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`, 
			ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if tag.RowsAffected() != int64(len(ids)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Insert ActionRequest (completion record)
		_, err = tx.Exec(ctx, `INSERT INTO "ActionRequest" 
			("tenantId", "actorId", operation, key, "requestHash", response) 
			VALUES ($1, $2, $3, $4, $5, $6::jsonb)`, 
			u.Tenant, u.User, "bulk-approve.v3", key, requestHash, responseBytes)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Insert ApprovalAudit for each approved purchase
		for _, id := range ids {
			_, err = tx.Exec(ctx, `INSERT INTO "ApprovalAudit" 
				("tenantId", "purchaseId", "approvedBy", operation, "idempotencyKey", "fromStatus", "toStatus") 
				VALUES ($1, $2, $3, $4, $5, $6, $7)`, 
				u.Tenant, id, u.User, "bulk-approve.v3", key, "submitted", "approved")
			if err != nil {
				return protocol.Result{}, false, err
			}
		}

		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}

		return protocol.Result{ApprovedIDs: sortedIDs}, false, nil
	}

	return protocol.HTTP(approve, fallback), nil
}

